const cfg = $('Set — Window config').first().json;
const windowMinutes = Number(cfg.window_minutes) || 30;
const minReports = Number(cfg.min_reports) || 3;
const minSpanMinutes = Number(cfg.min_span_minutes) || 10;
const maxImages = Number(cfg.max_images) || 6;

const reports = items.map(i => i.json).filter(r => r.screenshot_url && r.created_at);

if (!reports.length) {
  return [{ json: { enough: false, idle: null, reason: 'no_reports_with_screenshot', reports_in_window: 0, window_minutes: windowMinutes } }];
}

// The most recent report acts as "the one that just arrived" (window anchor)
reports.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
const anchor = new Date(reports[0].created_at).getTime();
const cutoff = anchor - windowMinutes * 60 * 1000;
const inWindow = reports.filter(r => new Date(r.created_at).getTime() >= cutoff);

if (inWindow.length < minReports) {
  return [{ json: {
    enough: false, idle: null, reason: 'not_enough_reports',
    reports_in_window: inWindow.length, min_reports: minReports, window_minutes: windowMinutes,
    anchor_report: reports[0].key, anchor_at: reports[0].created_at
  } }];
}

inWindow.sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
const spanMinutes = (new Date(inWindow[inWindow.length - 1].created_at) - new Date(inWindow[0].created_at)) / 60000;

if (spanMinutes < minSpanMinutes) {
  return [{ json: {
    enough: false, idle: null, reason: 'insufficient_time_span',
    span_minutes_observed: Math.round(spanMinutes * 10) / 10, min_span_minutes: minSpanMinutes,
    reports_in_window: inWindow.length, window_minutes: windowMinutes,
    anchor_report: reports[0].key, anchor_at: reports[0].created_at
  } }];
}

// Evenly sample down to maxImages, always keeping the first and the last
let sampled = inWindow;
if (inWindow.length > maxImages && maxImages >= 2) {
  const picks = new Set();
  for (let i = 0; i < maxImages; i++) picks.add(Math.round(i * (inWindow.length - 1) / (maxImages - 1)));
  sampled = [...picks].sort((a, b) => a - b).map(idx => inWindow[idx]);
}

return sampled.map(r => ({ json: {
  enough: true, key: r.key, created_at: r.created_at, screenshot_url: r.screenshot_url,
  window_minutes: windowMinutes,
  reports_in_window: inWindow.length,
  span_minutes_observed: Math.round(spanMinutes * 10) / 10
} }));

const filt = $('Code — Filter report window').all().map(i => i.json);
const content = [];

for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary && items[i].binary.data;
  if (!bin) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let mime = (bin.mimeType || 'image/jpeg').split(';')[0];
  if (!['image/jpeg', 'image/png', 'image/gif', 'image/webp'].includes(mime)) mime = 'image/jpeg';
  content.push({ type: 'text', text: `Screenshot ${i + 1} — taken ${filt[i].created_at}` });
  content.push({ type: 'image', source: { type: 'base64', media_type: mime, data: buf.toString('base64') } });
}

const win = filt[0].window_minutes;
content.push({ type: 'text', text:
  `These are ${items.length} screenshots of the same computer, in chronological order, within a ${win}-minute window. ` +
  'Compare them and determine whether there are changes that indicate human activity: windows changing, new or edited text, scrolling, different applications, different content. ' +
  'IGNORE trivial changes: the system clock, battery/wifi indicators, transient notifications, background animations, or minimal pixel differences. ' +
  'Reply ONLY with valid JSON, no markdown or extra text, with this exact shape: ' +
  '{"change_detected": true|false, "summary": "brief explanation of what changed or why it looks inactive"}'
});

return [{ json: {
  anthropic_body: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 500,
    messages: [{ role: 'user', content }]
  },
  meta: {
    count: items.length,
    reports_in_window: filt[0].reports_in_window,
    span_minutes_observed: filt[0].span_minutes_observed,
    window_minutes: win,
    from: filt[0].created_at,
    to: filt[filt.length - 1].created_at,
    keys: filt.map(f => f.key)
  }
} }];

const resp = $input.first().json;
const meta = $('Code — Build Claude vision request').first().json.meta;

// Stamp the cooldown clock first: this run paid a vision call, parseable or not
const staticData = $getWorkflowStaticData('global');
staticData.last_analysis_at = new Date().toISOString();

let text = '';
if (resp.content && resp.content.length) {
  text = resp.content.filter(c => c.type === 'text').map(c => c.text).join('\n');
}

let verdict = null;
try {
  verdict = JSON.parse(text.replace(/```json|```/g, '').trim());
} catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) { try { verdict = JSON.parse(m[0]); } catch (e2) {} }
}

if (!verdict || typeof verdict.change_detected !== 'boolean') {
  return [{ json: {
    idle: null, change_detected: null, reason: 'unparseable_model_response',
    raw_response: text, reports_analyzed: meta.count, reports_in_window: meta.reports_in_window,
    span_minutes_observed: meta.span_minutes_observed, report_keys: meta.keys,
    window_minutes: meta.window_minutes, from: meta.from, to: meta.to
  } }];
}

return [{ json: {
  idle: !verdict.change_detected,
  change_detected: verdict.change_detected,
  reason: verdict.change_detected ? 'changes_between_screenshots' : 'no_changes_detected',
  summary: verdict.summary || '',
  reports_analyzed: meta.count,
  reports_in_window: meta.reports_in_window,
  span_minutes_observed: meta.span_minutes_observed,
  report_keys: meta.keys,
  window_minutes: meta.window_minutes,
  from: meta.from, to: meta.to
} }];

const cfg = $('Set — Window config').first().json;
const cooldownMinutes = Number(cfg.cooldown_minutes) || 0;
const staticData = $getWorkflowStaticData('global');
const last = staticData.last_analysis_at ? new Date(staticData.last_analysis_at).getTime() : 0;

// Note: static data only persists in production executions,
// so manual test runs are never blocked by the cooldown.
if (cooldownMinutes > 0 && last && Date.now() - last < cooldownMinutes * 60 * 1000) {
  return [{ json: {
    skipped: true, reason: 'cooldown',
    last_analysis_at: new Date(last).toISOString(),
    next_eligible_at: new Date(last + cooldownMinutes * 60 * 1000).toISOString(),
    cooldown_minutes: cooldownMinutes
  } }];
}

return [{ json: { skipped: false, cooldown_minutes: cooldownMinutes } }];
